#include "../cpu_conditional_oracle.h"
int main(int argc,char**argv){std::ifstream f(argv[1],std::ios::binary|std::ios::ate);int count=f.tellg()/8;f.seekg(0);std::vector<double>x(count);f.read((char*)x.data(),count*8);for(int step=0;7900+(step+1)*6812<=count;step++){int st=7900+step*6812;int prev=step?7900+(step-1)*6812+9+615:7+545*3;int after=st+9+615;for(int i=0;i<513;i++){uint32_t beforewords[12],afterwords[12];for(int j=0;j<12;j++){beforewords[j]=x[prev+16+i*12+j];afterwords[j]=x[after+16+i*12+j];}StudyRNG a,b;memcpy(&a,beforewords,48);memcpy(&b,afterwords,48);float shape=float(x[st+1])+i%7,rate=float(x[st+2])+.5f+(i%13)*.125f;if(step==21&&i==145){StudyRNG q=a;float z=normal(q),u=uniform(q),d=shape-1.f/3.f,c=1.f/sqrtf(9.f*d),v=powf(fmaf(c,z,1.f),3.f);float rhs=fmaf(d,logf(v),fmaf(-d,v,fmaf(z,.5f*z,d)));printf("FIRST z%.12g u%.12g d%.12g c%.12g v%.12g logu%.12g rhs%.12g margin%.12g\n",z,u,d,c,v,logf(u),rhs,logf(u)-rhs);}StudyRNG ref=a;float value=conditional_cpu(ref,shape,rate),actual=x[st+9+16+i];bool eq=ref.d==b.d&&ref.flag==b.flag;for(int j=0;j<5;j++)eq&=ref.v[j]==b.v[j];if(fabs(value-actual)>3e-5||!eq){printf("step%d i%d shape%.9g rate%.9g actual%.9g ref%.9g delta%.9g stateeq%d beforeflag%d beforeextra%.9g afterextra%.9g refextra%.9g d_before%u d_actual%u d_ref%u\n",step,i,shape,rate,actual,value,value-actual,eq,a.flag,a.extra,b.extra,ref.extra,a.d,b.d,ref.d);}}}}
